private struct Flow:View{@State var p:Page;init(){let a=ProcessInfo.processInfo.arguments.first{$0.hasPrefix("--screen=")};let v=a.map{String($0.dropFirst(9))};_p=State(initialValue:v.flatMap(Page.init(rawValue:)) ?? .home)};var body:some View{GeometryReader{g in let s=min(g.size.width/402,g.size.height/874);Group{switch p{case .home:Home(p:$p);case .detail:Detail(p:$p);case .host:Host(p:$p);case .roll:Roll(p:$p);case .result:Result(p:$p);case .setup:Setup(p:$p)}}.frame(width:402,height:874).scaleEffect(s,anchor:.topLeading).frame(width:402*s,height:874*s).frame(maxWidth:.infinity,maxHeight:.infinity,alignment:.top)}.background(P.bg).ignoresSafeArea()}}
private extension View{func at(_ x:CGFloat,_ y:CGFloat,_ w:CGFloat,_ h:CGFloat)->some View{frame(width:w,height:h,alignment:.topLeading).offset(x:x,y:y)}}

